/**
 * Utility: Chuyển đổi Uint8Array sang Base64
 */
function bufferToBase64(buffer) {
    const bytes = new Uint8Array(buffer);
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}
/**
 * Utility: Chuyển đổi Base64 sang Uint8Array
 */
function base64ToBuffer(base64) {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
}
/**
 * [OPTIMIZED] Sinh cặp khóa ECDSA (Public / Private Key) sử dụng Web Crypto API.
 * Đảm bảo tương thích với Trình duyệt, Tauri và Cloudflare Workers.
 */
export async function generateECDSAKeyPair() {
    // eslint-disable-next-line no-undef
    const cryptoAPI = globalThis.crypto;
    const keyPair = await cryptoAPI.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify']);
    const publicKeyJwk = await cryptoAPI.subtle.exportKey('jwk', keyPair.publicKey);
    const privateKeyJwk = await cryptoAPI.subtle.exportKey('jwk', keyPair.privateKey);
    return { publicKeyJwk, privateKeyJwk };
}
/**
 * [OPTIMIZED] Ký một chuỗi Payload bằng Web Crypto API.
 */
export async function signPayload(payload, privateKeyJwk) {
    const cryptoAPI = globalThis.crypto;
    const privateKey = await cryptoAPI.subtle.importKey('jwk', privateKeyJwk, { name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign']);
    const encoder = new TextEncoder();
    const data = encoder.encode(payload);
    const signatureBuffer = await cryptoAPI.subtle.sign({ name: 'ECDSA', hash: { name: 'SHA-256' } }, privateKey, data);
    return bufferToBase64(signatureBuffer);
}
/**
 * [OPTIMIZED] Xác thực chữ ký bằng Public Key (Web Crypto API).
 */
export async function verifySignature(payload, signatureBase64, publicKeyJwk) {
    const cryptoAPI = globalThis.crypto;
    const publicKey = await cryptoAPI.subtle.importKey('jwk', publicKeyJwk, { name: 'ECDSA', namedCurve: 'P-256' }, true, ['verify']);
    const encoder = new TextEncoder();
    const data = encoder.encode(payload);
    const signatureBytes = base64ToBuffer(signatureBase64);
    return await cryptoAPI.subtle.verify({ name: 'ECDSA', hash: { name: 'SHA-256' } }, publicKey, signatureBytes, data);
}
