import { Hono } from 'hono';
import { cors } from 'hono/cors';
import * as jose from 'jose';
import { verifySignature } from '@dichomnion/crypto-utils';
import { JobRequest, deterministicStringify } from '@dichomnion/shared-types';

type Bindings = {
  KV_CACHE: KVNamespace;
};

const app = new Hono<{ Bindings: Bindings }>();

// Bật CORS cho toàn bộ API để Client gọi được
app.use('/api/*', cors({
  origin: '*', // Trong production nên giới hạn origin
  allowHeaders: ['Content-Type', 'X-ECDSA-Signature', 'X-Device-Id'],
  allowMethods: ['POST', 'GET', 'OPTIONS'],
}));

app.get('/', (c) => c.text('OmniVoice Gateway is running! Secure Edge Active.'));

// ENDPOINT ĐĂNG KÝ: Nơi duy nhất được phép nhận Public Key
app.post('/api/auth/register', async (c) => {
  try {
    const body = await c.req.json();
    if (!body.publicKeyJwk) {
      return c.json({ error: 'Missing Public Key' }, 400);
    }
    
    // Cấp phát Device ID mới
    const deviceId = crypto.randomUUID();
    
    // Lưu vào KV Store thực tế
    await c.env.KV_CACHE.put(deviceId, JSON.stringify(body.publicKeyJwk));
    
    return c.json({ deviceId, message: 'Device Registered Successfully' }, 201);
  } catch (e) {
    return c.json({ error: 'Invalid Request' }, 400);
  }
});

app.post('/api/jobs/create', async (c) => {
  const signature = c.req.header('X-ECDSA-Signature');
  const deviceId = c.req.header('X-Device-Id'); 

  if (!signature || !deviceId) {
    return c.json({ error: 'Missing Zero-Trust Signature or Device ID' }, 401);
  }

  // TRUY XUẤT KHÓA TỪ DATABASE: Không bao giờ tin tưởng Header!
  const publicKeyJwk: JsonWebKey | null = await c.env.KV_CACHE.get(deviceId, { type: "json" });
  
  if (!publicKeyJwk) {
    return c.json({ error: 'Unauthorized Device. Public Key not found in Registry.' }, 401);
  }

  // Nhận body gốc dạng chữ
  const rawBody = await c.req.text();
  
  // Ép định dạng chữ về chuẩn Deterministic trước khi check
  let payloadObj: JobRequest;
  try {
    payloadObj = JSON.parse(rawBody);
  } catch(e) {
    return c.json({ error: 'Invalid JSON' }, 400);
  }
  
  const payloadStr = deterministicStringify(payloadObj);
  
  // Xác thực chữ ký
  const isValid = await verifySignature(payloadStr, signature, publicKeyJwk);
  if (!isValid) {
    return c.json({ error: 'Tampering Detected. Signature Invalid.' }, 403);
  }

  // Check Timestamp
  const now = Date.now();
  if (now - payloadObj.timestamp > 30000) { 
    return c.json({ error: 'Request Expired. Replay attack prevented.' }, 403);
  }
  
  // TRẠM 3 (PHẦN 1): Bắt đầu bấm giờ đo đạc Anti-Fraud
  const startTime = Date.now();
  
  // TRẠM 2: Tạo JWT (Gateway Signature) để chứng minh thân phận với GPU Worker
  const secret = new TextEncoder().encode('OMNIVOICE_ZERO_TRUST_INTERNAL_V1');
  const gatewayJwt = await new jose.SignJWT({ authorized: true, role: 'gateway' })
    .setProtectedHeader({ alg: 'HS256' })
    .setIssuedAt()
    .setExpirationTime('1m') // Token sống đúng 1 phút
    .sign(secret);
    
  // TÍCH HỢP GPU WORKER (Tự động Forward Job)
  try {
    const gpuWorkerUrl = 'http://127.0.0.1:8000/api/worker/process';
    
    const workerPayload = {
      job_id: payloadObj.jobId,
      audio_url: payloadObj.videoAudioUrl,
      target_language: payloadObj.config.targetLanguage,
      translation_style: payloadObj.config.translationStyle,
      segments: payloadObj.segments || [] // Bổ sung segments
    };

    const workerRes = await fetch(gpuWorkerUrl, {
      method: 'POST',
      headers: { 
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${gatewayJwt}` // Kẹp Token vào Header
      },
      body: JSON.stringify(workerPayload)
    });
    
    if (!workerRes.ok) {
      if (workerRes.status === 403) {
        return c.json({ error: 'Worker Rejected Gateway (Signature Mismatch)' }, 403);
      }
      return c.json({ error: 'GPU Worker failed to process job' }, 500);
    }
    
    const workerData = await workerRes.json();
    
    // TRẠM 3 (PHẦN 2): Kiểm tra Anti-Fraud Time
    const elapsed = Date.now() - startTime;
    // Bỏ qua check fraud khi dùng LLM gọi API ngoài (thường tốn > 2000ms nên không lo)
    // Nếu vẫn test thì nên cẩn thận vì LLM real có thể mất 3-10 giây!
    
    return c.json({ 
      message: 'Job Processed by GPU Worker!', 
      gatewayJobId: payloadObj.jobId,
      timeElapsedMs: elapsed,
      workerResult: workerData
    }, 200); 

  } catch (error) {
    return c.json({ error: 'Failed to contact GPU Worker. Is it running?' }, 500);
  }
});

export default app;
